import * as AlertDialog from '@radix-ui/react-alert-dialog';

import type { ModalActionProps } from '../Modal.types';

export const ModalAction = ({ children }: ModalActionProps): JSX.Element => (
  <AlertDialog.Action asChild>{children}</AlertDialog.Action>
);

ModalAction.displayName = 'Modal.Action';
